import * as T from './vendor/three.module.js';
export function installLibrary({scene,camera,colliders,pause,rewards,getNearbyPlaces=()=>[],getCurrentSeat=()=>null}){
 const root=new T.Group();root.name='Library of Alexandria';scene.add(root);
 const mat=color=>new T.MeshStandardMaterial({color,roughness:.7}),stone=mat('#eee0c6'),navy=mat('#183e64'),gold=mat('#d4ad54'),wood=mat('#67452e'),paper=mat('#fff1cb');
 const add=(geo,m,x,y,z)=>{const o=new T.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=add(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.3,d:d/2+.3});return o;};
 // Open doorway, generous aisle and a terrace connected to the square.
 box(30,.09,41,17,.16,24,stone);box(20,.08,54,25,.14,3,stone);box(30,.09,52,5,.16,7,stone);
 box(30,2.7,29,16,5.4,.3,stone,true);for(const x of [22,38]){box(x,.8,36,.3,1.6,14,stone,true);box(x,4.6,36,.3,1.6,14,stone);for(const z of [30,35,42])box(x,2.7,z,.4,5.4,.4,navy,true);}
 for(const x of [25,35])box(x,2.7,43,6,5.4,.3,stone,true);box(30,4.8,43,4,1.2,.3,navy);box(30,5.5,36,17,.3,15,navy);box(30,5.72,36,17.3,.14,15.3,gold);
 const glass=new T.MeshPhysicalMaterial({color:'#8bbbd5',transparent:true,opacity:.25,roughness:.2,side:T.DoubleSide,depthWrite:false});for(const x of [22.02,37.98])box(x,2.7,36,.04,2.2,12,glass);
 function sign(lines,x,y,z,w,h){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#183e64';ctx.fillRect(0,0,1024,256);ctx.fillStyle='#fff0c7';ctx.textAlign='center';lines.forEach((s,i)=>{ctx.font=(i?'30':'46')+'px Georgia';ctx.fillText(s,512,90+i*85);});const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;add(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign(['LIBRARY OF ALEXANDRIA','Community idea: @Jauregui9821'],30,4.85,43.2,10,1.4);
 const colors=['#214e71','#a64a53','#5c7256','#c29a4e'].map(mat);
 for(const x of [25.5,34.5]){box(x,1.7,30.2,5,3.2,.65,wood,true);for(let row=0;row<3;row++){box(x,.6+row,30.6,5,.12,.6,gold);for(let i=0;i<12;i++)box(x-2.2+i*.39,1+row,30.65,.27,.55+(i%3)*.09,.36,colors[(i+row)%4]);}}
 const seats=[];for(const x of [26,34]){box(x,.95,34.5,2.5,.15,1.3,wood,true);for(const dx of [-1,1])box(x+dx,.45,34.5,.12,.9,.7,gold);box(x,.6,36.2,.9,.18,.85,navy,true);box(x,1.05,36.6,.9,.85,.12,navy);seats.push({name:'Alexandria reading chair',x,z:36.2,y:1.4,yaw:0,approach:{x,z:37.6},kind:'library'});box(x,1.06,34.5,.8,.07,.6,paper);}
 box(30,.9,38,1.8,1.6,.75,wood,true);box(30,1.75,38,2,.15,1,gold);sign(['READ · DISCOVER · IMAGINE','Explore three short community readings'],30,2.35,38.08,3.5,.8);
 for(const x of [25,35]){box(x,.6,50,3,.18,.9,wood,true);box(x,1.05,50.4,3,.8,.12,navy);seats.push({name:'Alexandria reading terrace bench',x,z:50,y:1.4,yaw:0,approach:{x,z:48.7},kind:'library'});}
 box(35,.8,47,1.4,.12,1.1,wood,true);box(35,.4,47,.18,.8,.18,gold);add(new T.CylinderGeometry(.14,.1,.23,12),paper,34.7,.98,47);for(let i=0;i<3;i++)add(new T.SphereGeometry(.11,8,6),gold,35.1+i*.12,.98,47);
 sign(['READING TERRACE','Virtual tea · oat bites · bookmark keepsake'],30,2.7,51.5,6,.85);for(const x of [27,33])box(x,1.3,51.5,.1,2.6,.1,gold,true);
 const deskPoint={x:30,z:40,name:'Library of Alexandria reading desk'},terracePoint={x:30,z:48,name:'Alexandria reading terrace'};
 const near=()=>Math.hypot(camera.position.x-deskPoint.x,camera.position.z-deskPoint.z)<1.7;
 const canRead=()=>near()||seats.includes(getCurrentSeat());
 const chapters=[['Community beginnings','Krownlandia began on January 22, 2020, in the KROWN DAC and Token community. @gorayii contributed its name, and Lisa Chandler (@lisachandler) is its designer. Community members imagined places and activities together. What would make a shared town feel welcoming to you?'],['Places imagined together','The community plan names Eldergrove, Meadowbrook, Riverbend, Stonehearth, Sunvale and Whispering Pines. The Library of Alexandria was contributed by @Jauregui9821. These original ideas guide the growing world; the current prototype housing has its own names. Which place would you like to learn more about?'],['A page for tomorrow','A community grows through what people share: stories, skills, experiments and care. Imagine a book you would bring to this library. What could another visitor learn from it? This reading collection is a new interpretation for the current Krownlandia prototype, inspired by the original community library idea.']];
 const dialog=document.createElement('dialog');dialog.id='libraryMenu';dialog.setAttribute('aria-labelledby','libraryTitle');const title=document.createElement('h2');title.id='libraryTitle';title.textContent='Library of Alexandria';const credit=document.createElement('p');credit.textContent='Community place idea: @Jauregui9821. Explore three short readings, then collect your Alexandria Bookmark.';const tabs=document.createElement('div');tabs.id='libraryChapters';const story=document.createElement('section');story.id='libraryStory';const status=document.createElement('p');status.id='libraryStatus';status.setAttribute('role','status');const claim=document.createElement('button');claim.id='libraryClaim';const actions=document.createElement('div');actions.id='libraryActions';
 const seen=()=>new Set([0,1,2].filter(i=>rewards.state().done.includes('library-page-'+i))),buttons=[];let page=0;const owned=()=>rewards.state().done.includes('library-read');
 function render(){story.replaceChildren();const h=document.createElement('h3');h.textContent=chapters[page][0];const p=document.createElement('p');p.textContent=chapters[page][1];story.append(h,p);buttons.forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===page));b.textContent=(owned()||seen().has(i)?'✓ ':'')+(i+1)+'. '+chapters[i][0];});claim.disabled=owned()||seen().size<3;claim.textContent=owned()?'Alexandria Bookmark collected':'Collect Alexandria Bookmark';const collected=rewards.state().claims.includes('library:task');status.textContent=owned()?(collected?'Your Alexandria Bookmark and 20-point task reward are collected. You can display the bookmark at home.':'Your bookmark is collected. Your 20-point task reward is ready at the library rewards station.'):seen().size===3?'All three readings explored. Collect your Alexandria Bookmark below to unlock the 20-point task reward.':seen().size+' / 3 readings explored';rewardLink.textContent=owned()&&!collected?'Find my 20-point library reward':'Find library rewards';if(!rewards.state().saved)status.textContent+=' · Progress is available for this visit; browser storage is unavailable.';}
 chapters.forEach((c,i)=>{const b=document.createElement('button');b.id='libraryChapter-'+i;b.textContent=(i+1)+'. '+c[0];b.onclick=()=>{if(!dialog.open||!canRead())return;page=i;rewards.recordLibraryPage(i);render();};tabs.append(b);buttons.push(b);});claim.onclick=()=>{if(dialog.open&&canRead()&&seen().size===3&&!owned()){rewards.completeLibrary();render();}};
 function action(id,label,fn){const b=document.createElement('button');b.id=id;b.textContent=label;b.onclick=()=>{if(!dialog.open||b.disabled)return;fn();};actions.append(b);return b;}
 action('libraryTerrace','Relax on the reading terrace',()=>{rewards.guideToPoint(terracePoint);dialog.close();});const rewardLink=action('libraryRewards','Find library rewards',()=>{rewards.guideTo('library');dialog.close();});action('libraryClose','Return to the library',()=>{pause();dialog.close();});dialog.append(title,credit,tabs,story,status,claim,actions);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='library.css';document.head.append(css);
 const nearby=document.createElement('details');nearby.id='libraryNearby';const nearbyTitle=document.createElement('summary');nearbyTitle.textContent='Explore nearby';const nearbyList=document.createElement('div');nearby.append(nearbyTitle,nearbyList);dialog.replaceChildren(title,credit,tabs,story,status,claim,nearby,actions);
 function refreshNearby(){nearby.open=false;nearbyList.replaceChildren();for(const point of getNearbyPlaces()){const button=document.createElement('button');button.id='libraryWalk-'+point.id;button.textContent='Walk to '+point.name;button.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideToPoint({x:point.x,z:point.z,name:point.name});dialog.close();};nearbyList.append(button);}nearby.hidden=nearbyList.children.length===0;}
 return {seats,deskPoint,terracePoint,progress:()=>({count:owned()?3:seen().size}),collection:()=>owned()?[{id:'alexandria-bookmark',name:'Alexandria Bookmark',color:'#d4ad54'}]:[],open(){if(!canRead()||dialog.open)return false;pause();const unread=[0,1,2].find(i=>!seen().has(i));if(!owned()&&unread!==undefined)page=unread;rewards.recordLibraryPage(page);render();refreshNearby();dialog.showModal();return true;},get near(){return near()},get isOpen(){return dialog.open}};
}
